insert into category_three.question_bank (id, prompt, theme, answers, sort_order, version)
select r->>'id', r->>'prompt', r->>'theme', array(select jsonb_array_elements_text(r->'answers')), (r->>'sort_order')::int, r->>'version'
from jsonb_array_elements('[{"id":"funny-1","prompt":"Your body just hired a lawyer. What’s the first right it demands back?","theme":"Body & Autonomy","answers":["Being able to say no","Choosing their own care","Choosing their own pace","Choosing how they present themselves"],"sort_order":1,"version":"funny"},{"id":"funny-2","prompt":"Your body wants to resign from modern life. What’s probably the final straw?","theme":"Body & Autonomy","answers":["A rigid schedule","Too little rest","Constant monitoring","Pressure to stay productive"],"sort_order":2,"version":"funny"},{"id":"funny-3","prompt":"The CEO of ''You'' is rewriting the rulebook. What freedom goes on page one?","theme":"Body & Autonomy","answers":["Freedom to refuse","Freedom to change your mind","Freedom to set boundaries","Freedom to ask for support"],"sort_order":3,"version":"funny"},{"id":"funny-4","prompt":"Your body sends a notification you’ve ignored all day. What does it say?","theme":"Body & Autonomy","answers":["Fatigue","Hunger","Tension","Need for movement"],"sort_order":4,"version":"funny"},{"id":"funny-5","prompt":"A choice looks personal, but one invisible pressure is shouting in the background. Name it.","theme":"Body & Autonomy","answers":["Money pressure","Social pressure","Work pressure","Expert authority"],"sort_order":5,"version":"funny"},{"id":"funny-6","prompt":"Which personal boundary is most likely to need its own security guard?","theme":"Body & Autonomy","answers":["Your time","Your personal space","Your privacy","Your need for rest"],"sort_order":6,"version":"funny"},{"id":"funny-7","prompt":"What’s a sign that daily life was designed by humans instead of productivity robots?","theme":"Body & Autonomy","answers":["Enough sleep","Flexible time","Quiet breaks","Unhurried care"],"sort_order":7,"version":"funny"},{"id":"funny-8","prompt":"What makes someone think, ''Okay, I’m being treated like a person here''?","theme":"Body & Autonomy","answers":["Being listened to","Being asked for consent","Being given enough time","Being trusted"],"sort_order":8,"version":"funny"},{"id":"funny-9","prompt":"If freedom had a physical feeling, what would it probably feel like?","theme":"Body & Autonomy","answers":["Relaxed breathing","Steady energy","Less tension","Easier movement"],"sort_order":9,"version":"funny"},{"id":"funny-10","prompt":"Before becoming a productivity machine, what basic human need deserves top billing?","theme":"Body & Autonomy","answers":["Rest","Nourishment","Movement","Connection"],"sort_order":10,"version":"funny"},{"id":"funny-11","prompt":"What makes someone think, ''Am I a person or just a very complicated tool?''","theme":"Body & Autonomy","answers":["Output being measured","Discomfort being ignored","Breaks being timed","Appearance being judged"],"sort_order":11,"version":"funny"},{"id":"funny-12","prompt":"You’ve stolen one hour back from modern life. What do you do with it first?","theme":"Body & Autonomy","answers":["Choosing their pace","Taking real rest","Moving freely","Disconnecting for a while"],"sort_order":12,"version":"funny"},{"id":"funny-13","prompt":"What’s the secret ingredient that makes bodily autonomy actually possible?","theme":"Body & Autonomy","answers":["Good information","Enough time","Enough resources","Supportive people"],"sort_order":13,"version":"funny"},{"id":"funny-14","prompt":"Why can a supposedly ''personal choice'' arrive with a whole committee attached?","theme":"Body & Autonomy","answers":["Options depend on cost","Family duties shape options","Work rules shape options","Culture shapes expectations"],"sort_order":14,"version":"funny"},{"id":"funny-15","prompt":"What’s the green flag that says an institution actually respects your body?","theme":"Body & Autonomy","answers":["Clear consent","Accessible choices","Privacy","A real right to refuse"],"sort_order":15,"version":"funny"},{"id":"funny-16","prompt":"When your body and an expert disagree, what kind of knowledge deserves a seat at the table?","theme":"Body & Autonomy","answers":["Lived experience","Repeated body signals","Personal limits","Informed professional advice"],"sort_order":16,"version":"funny"},{"id":"funny-17","prompt":"Your body has had enough of overwork. How does it file a complaint?","theme":"Body & Autonomy","answers":["Exhaustion","Loss of focus","Irritability","Need for sleep"],"sort_order":17,"version":"funny"},{"id":"funny-18","prompt":"Name a tiny freedom that feels surprisingly luxurious once someone takes it away.","theme":"Body & Autonomy","answers":["Choosing when to rest","Choosing how to move","Choosing what to wear","Choosing when to be alone"],"sort_order":18,"version":"funny"},{"id":"funny-19","prompt":"What quietly turns ''my life'' into ''someone else’s schedule''?","theme":"Body & Autonomy","answers":["Rigid scheduling","Constant ranking","Constant tracking","Constant comparison"],"sort_order":19,"version":"funny"},{"id":"funny-20","prompt":"If your body were a roommate, what would keep the relationship peaceful?","theme":"Body & Autonomy","answers":["Listening","Patience","Curiosity","Compassion"],"sort_order":20,"version":"funny"},{"id":"funny-21","prompt":"Your job gets one humanizing upgrade. What should it be?","theme":"Work, Time & Productivity","answers":["Control over pace","Meaningful tasks","Enough time","Supportive people"],"sort_order":21,"version":"funny"},{"id":"funny-22","prompt":"What turns a normal job into ''Congratulations, you are now a machine''?","theme":"Work, Time & Productivity","answers":["Repeated tasks","Constant timers","No real decisions","Nonstop monitoring"],"sort_order":22,"version":"funny"},{"id":"funny-23","prompt":"What’s the worst souvenir people bring home from being overworked?","theme":"Work, Time & Productivity","answers":["Losing personal time","Losing connection with others","Constant fatigue","No mental space"],"sort_order":23,"version":"funny"},{"id":"funny-24","prompt":"What proves someone did good work besides producing a mountain of stuff?","theme":"Work, Time & Productivity","answers":["Quality","Sustainability","Usefulness","Learning"],"sort_order":24,"version":"funny"},{"id":"funny-25","prompt":"Besides money, what makes a job feel like it’s not stealing your soul?","theme":"Work, Time & Productivity","answers":["Respect","Purpose","Control","Belonging"],"sort_order":25,"version":"funny"},{"id":"funny-26","prompt":"Workplace pressure walks into the room wearing four disguises. Name one.","theme":"Work, Time & Productivity","answers":["Pressure to go faster","Pressure to be always available","Pressure to hit targets","Pressure to monitor yourself"],"sort_order":26,"version":"funny"},{"id":"funny-27","prompt":"What’s the workplace freedom people notice most when they finally get it?","theme":"Work, Time & Productivity","answers":["Choosing how to work","Choosing their pace","Choosing when to pause","Having a real voice"],"sort_order":27,"version":"funny"},{"id":"funny-28","prompt":"What can make an eight-hour shift feel approximately fourteen years long?","theme":"Work, Time & Productivity","answers":["Unpredictability","Repetition","Surveillance","Meaningless tasks"],"sort_order":28,"version":"funny"},{"id":"funny-29","prompt":"Modern life puts a price tag on time. What does it treat time like?","theme":"Work, Time & Productivity","answers":["Money","A schedule","A target","A resource"],"sort_order":29,"version":"funny"},{"id":"funny-30","prompt":"You get one truly useful break in a long day. What kind do you choose?","theme":"Work, Time & Productivity","answers":["Quiet time","A little movement","A good conversation","Time outdoors"],"sort_order":30,"version":"funny"},{"id":"funny-31","prompt":"What keeps someone from writing ''I quit'' on a sticky note and walking out?","theme":"Work, Time & Productivity","answers":["Fair pay","Manageable hours","Respect","Autonomy"],"sort_order":31,"version":"funny"},{"id":"funny-32","prompt":"If robots are taking tasks, which tasks should humans happily wave goodbye to first?","theme":"Work, Time & Productivity","answers":["Repetitive tasks","Dangerous tasks","Administrative tasks","After-hours tasks"],"sort_order":32,"version":"funny"},{"id":"funny-33","prompt":"When ''efficiency'' becomes the boss of everything, what gets kicked out first?","theme":"Work, Time & Productivity","answers":["People get rushed","Care gets reduced","Creativity gets reduced","Rest disappears"],"sort_order":33,"version":"funny"},{"id":"funny-34","prompt":"The future of work gets one wish. What would make it more human?","theme":"Work, Time & Productivity","answers":["Shorter workdays","Flexible hours","Shared decisions","Stable security"],"sort_order":34,"version":"funny"},{"id":"funny-35","prompt":"Name work that somehow takes real effort while remaining magically invisible.","theme":"Work, Time & Productivity","answers":["Planning","Emotional support","Caregiving","Household coordination"],"sort_order":35,"version":"funny"},{"id":"funny-36","prompt":"What do people often mistake for productivity because the calendar looks terrifying?","theme":"Work, Time & Productivity","answers":["Being useful","Being responsible","Being important","Being productive"],"sort_order":36,"version":"funny"},{"id":"funny-37","prompt":"What’s the fastest recipe for burnout?","theme":"Work, Time & Productivity","answers":["No control","No rest","No recognition","No boundaries"],"sort_order":37,"version":"funny"},{"id":"funny-38","prompt":"What tells you a workplace remembers employees have actual bodies?","theme":"Work, Time & Productivity","answers":["Real breaks","A safe pace","Reasonable hours","Comfortable working conditions"],"sort_order":38,"version":"funny"},{"id":"funny-39","prompt":"On a normal weekday, who seems to own most of your time?","theme":"Work, Time & Productivity","answers":["Yourself","Your family","Your school or workplace","Your community"],"sort_order":39,"version":"funny"},{"id":"funny-40","prompt":"After a brutal day, what’s the closest thing to a human reboot button?","theme":"Work, Time & Productivity","answers":["Sleep","A walk","Talking with someone","A creative hobby"],"sort_order":40,"version":"funny"},{"id":"funny-41","prompt":"Name a form of care everyone needs but nobody seems to put on the invoice.","theme":"Care, Family & Everyday Support","answers":["Listening","Planning","Cleaning","Reminding"],"sort_order":41,"version":"funny"},{"id":"funny-42","prompt":"What turns caregiving from loving into ''I have not sat down since Tuesday''?","theme":"Care, Family & Everyday Support","answers":["Not enough time","Not enough money","Not enough help","Not enough recognition"],"sort_order":42,"version":"funny"},{"id":"funny-43","prompt":"What makes family responsibility feel like teamwork instead of a group project gone wrong?","theme":"Care, Family & Everyday Support","answers":["Shared tasks","Shared decisions","Shared time","Shared responsibility"],"sort_order":43,"version":"funny"},{"id":"funny-44","prompt":"If care had a fuel tank, what would run out first?","theme":"Care, Family & Everyday Support","answers":["Time","Patience","Money","Community"],"sort_order":44,"version":"funny"},{"id":"funny-45","prompt":"What does society desperately need while pretending it happens by magic?","theme":"Care, Family & Everyday Support","answers":["Child care","Elder care","Emotional support","Household work"],"sort_order":45,"version":"funny"},{"id":"funny-46","prompt":"What small act says ''I care'' louder than a dramatic speech?","theme":"Care, Family & Everyday Support","answers":["Showing up","Checking in","Helping practically","Making time"],"sort_order":46,"version":"funny"},{"id":"funny-47","prompt":"What makes caring for family feel chosen instead of assigned?","theme":"Care, Family & Everyday Support","answers":["Support","Resources","Flexibility","Respect"],"sort_order":47,"version":"funny"},{"id":"funny-48","prompt":"Your neighborhood starts a ''share more, struggle less'' club. What should people share first?","theme":"Care, Family & Everyday Support","answers":["Child care","Meals","Transportation","Useful information"],"sort_order":48,"version":"funny"},{"id":"funny-49","prompt":"When every caring job gets dumped on one person, what grows fastest?","theme":"Care, Family & Everyday Support","answers":["Exhaustion","Isolation","Money pressure","Unequal roles"],"sort_order":49,"version":"funny"},{"id":"funny-50","prompt":"A new caregiver gets one support package. What should be inside?","theme":"Care, Family & Everyday Support","answers":["Paid time off","Affordable care","Nearby help","Flexible schedules"],"sort_order":50,"version":"funny"}]'::jsonb) r;